import XCTest
@testable import EFootballAssistant

final class RealGroqPipelineTests:XCTestCase{
    func testRealGroqJSONToDecisionAndVoice(){let json="""{"visible_players_count":8,"ball_visible":true,"free_space_visible":true,"game_context":"live_play","confidence":0.95,"recommendation":"Use o botão 'Dash & Pressure' para recuperar a posse de bola e pressione o adversário."}""";let exp=expectation(description:"pipeline");var spoken:[String]=[];let voice=VoiceEngine(onSpeak:{spoken.append($0)});let diagnostics=Diagnostics();let coordinator=DecisionCoordinator(voice:voice,diagnostics:diagnostics,minPriority:.medium);Task{let response=try! GroqResponseAdapter.decode(Data(json.utf8));let analysis=GroqResponseAdapter.frameAnalysis(from:response,timestamp:123);XCTAssertEqual(analysis.confidence,0.95);XCTAssertEqual(analysis.observedPlayersCount,8);XCTAssertTrue(analysis.ballObserved);XCTAssertEqual(analysis.freeSpacesObserved,1);XCTAssertNil(analysis.ball);XCTAssertEqual(analysis.recommendation?.message,"Use o botão 'Dash & Pressure' para recuperar a posse de bola e pressione o adversário.");let decision=await coordinator.process(analysis,groqLatencyMs:854.5);XCTAssertEqual(decision?.priority,.medium);XCTAssertEqual(spoken.count,1);XCTAssertTrue(spoken[0].contains("Dash & Pressure"));let events=await diagnostics.events;XCTAssertTrue(events.last?.message.contains("players=8") == true);XCTAssertTrue(events.last?.message.contains("ball_detected=true") == true);XCTAssertTrue(events.last?.message.contains("tts_triggered=true") == true);exp.fulfill()};waitForExpectations(timeout:2)}
    func testCooldownDoesNotSpeakSameRecommendationTwice(){let exp=expectation(description:"cooldown");var spokenCount=0;let voice=VoiceEngine(onSpeak:{_ in spokenCount += 1});let coordinator=DecisionCoordinator(voice:voice,minPriority:.medium);Task{let analysis=FrameAnalysis(timestamp:1,controlledPlayer:nil,confidence:0.9,recommendation:RecommendationPayload(type:.none,priority:.medium,message:"Direita"));_ = await coordinator.process(analysis,groqLatencyMs:1);_ = await coordinator.process(analysis,groqLatencyMs:1);XCTAssertEqual(spokenCount,1);exp.fulfill()};waitForExpectations(timeout:2)}
}
